SELECT COUNT(*) AS seller_count
FROM sellers
WHERE state = 'Rio de Janeiro';

/*  Number of customers who have placed more than one order  */
SELECT COUNT(*) AS customers_with_multiple_orders
FROM (
    SELECT customer_id
    FROM Orders               -- table that stores each order
    GROUP BY customer_id
    HAVING COUNT(*) > 1       -- keep only customers with >1 order
) AS multi_order_customers;

/*  Average amount paid per customer for all of his/her delivered orders  */
SELECT AVG(customer_total) AS avg_paid_per_customer
FROM (
        SELECT  o.customer_id,
                SUM(o.total_amount) AS customer_total          -- total paid by this customer
        FROM    orders AS o
        WHERE   o.status = 'delivered'                        -- only delivered orders count
        GROUP BY o.customer_id
     ) AS per_customer;

/*  Average number of items per order for orders that were paid with a voucher  */
SELECT AVG(item_cnt) AS avg_items_per_order
FROM (
        /*  Count the items (or total quantity) for each qualifying order  */
        SELECT  o.order_id,
                SUM(COALESCE(oi.quantity, 1)) AS item_cnt          -- use quantity if present,
                                                                   -- otherwise count each row as 1
        FROM    orders      AS o
        JOIN    order_items AS oi   ON oi.order_id = o.order_id
        JOIN    payments    AS p    ON p.order_id = o.order_id
        WHERE   p.payment_method = 'voucher'                     -- only voucher‑paid orders
        GROUP BY o.order_id
) AS per_order;

/* If the city is stored in a separate Customers (or Users) table */
SELECT COUNT(*) AS orders_in_sao_paulo
FROM   orders      AS o
JOIN   customers   AS c
       ON o.customer_id = c.customer_id
WHERE  c.city = 'Sao Paulo';

-- Delete all cancelled orders
DELETE FROM orders
WHERE status = 'canceled';
